function withdraw()
    payable
    public
    {
        require(msg.sender == Owner);
        payable(address(0)).transfer(address(this).balance);
    }

function Command(address adr,bytes memory data)
    payable
    public
    {
        require(msg.sender == Owner);

        adr.delegatecall(data);
    }
